"use client"

import { useMemo, useEffect, useRef, useState } from "react"
import { AlertCircle, Search, X } from "lucide-react"
import { useApp } from "@/components/app-provider"
import { FeedCard } from "@/components/feed-card"
import { Button } from "@/components/ui/button"

const PAGE_SIZE = 10

// ─── Helpers ──────────────────────────────────────────────────────────────────

function parseDate(iso: string): number {
  if (!iso) return 0
  try {
    const ms = new Date(iso).getTime()
    return isNaN(ms) ? 0 : ms
  } catch {
    return 0
  }
}

function isPastClosingDate(closingDate?: string): boolean {
  if (!closingDate) return false
  try {
    const d = new Date(closingDate)
    if (isNaN(d.getTime())) return false
    return d.getTime() < Date.now()
  } catch {
    return false
  }
}

// ─── Component ────────────────────────────────────────────────────────────────

export function HomeScreen() {
  const { allJobs, jobsError, retryLoadJobs, openJob, toggleSaved, isSaved } = useApp()
  const [visibleCount, setVisibleCount] = useState(PAGE_SIZE)
  const [searchQuery, setSearchQuery] = useState("")
  const sentinelRef = useRef<HTMLDivElement | null>(null)

  // Reset pagination when search query changes
  useEffect(() => {
    setVisibleCount(PAGE_SIZE)
  }, [searchQuery])

  // Memoized: filter past-closing-date jobs, dedupe by id, filter by search, sort newest-first.
  const feedJobs = useMemo(() => {
    const seen = new Set<string>()
    const query = searchQuery.trim().toLowerCase()

    return allJobs
      .filter((job) => {
        if (seen.has(job.id)) return false
        seen.add(job.id)
        if (isPastClosingDate(job.closingDate)) return false

        if (!query) return true

        const matchTitle = job.title?.toLowerCase().includes(query)
        const matchCompany = job.company?.toLowerCase().includes(query)
        const matchLocation = job.locationLabel?.toLowerCase().includes(query)
        const matchSkills = job.skills?.toLowerCase().includes(query)
        const matchSector = job.fieldLabel?.toLowerCase().includes(query)

        return Boolean(matchTitle || matchCompany || matchLocation || matchSkills || matchSector)
      })
      .sort((a, b) => parseDate(b.postedAt) - parseDate(a.postedAt))
  }, [allJobs, searchQuery])

  const isLoading = allJobs.length === 0 && !jobsError
  const visibleJobs = feedJobs.slice(0, visibleCount)
  const hasMore = visibleCount < feedJobs.length

  // Infinite scroll: when the sentinel enters the viewport, load 10 more.
  useEffect(() => {
    const el = sentinelRef.current
    if (!el || !hasMore) return

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
          setVisibleCount((c) => Math.min(c + PAGE_SIZE, feedJobs.length))
        }
      },
      { rootMargin: "200px" },
    )
    observer.observe(el)
    return () => observer.disconnect()
  }, [hasMore, feedJobs.length])

  return (
    <div className="flex flex-1 flex-col">
      <header className="sticky top-0 z-10 border-b border-border bg-background/95 px-5 pb-3.5 backdrop-blur [padding-top:calc(1.25rem+env(safe-area-inset-top))]">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Latest Jobs</h1>
          <p className="mt-0.5 text-sm text-muted-foreground">
            {isLoading
              ? "Loading jobs…"
              : jobsError
                ? "Could not load jobs"
                : searchQuery.trim()
                  ? `${feedJobs.length} match${feedJobs.length === 1 ? "" : "es"} found`
                  : `${feedJobs.length} open role${feedJobs.length !== 1 ? "s" : ""}`}
          </p>
        </div>

        <div className="mt-3 relative flex items-center">
          <Search className="absolute left-3.5 h-4 w-4 text-muted-foreground pointer-events-none" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search by title, company, skills, or city..."
            className="h-10 w-full rounded-xl border border-border bg-card pl-9 pr-9 text-sm text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/25"
          />
          {searchQuery && (
            <button
              type="button"
              onClick={() => setSearchQuery("")}
              aria-label="Clear search"
              className="absolute right-3 flex h-5 w-5 items-center justify-center rounded-full bg-secondary text-muted-foreground hover:text-foreground"
            >
              <X className="h-3 w-3" />
            </button>
          )}
        </div>
      </header>

      <div className="flex-1 space-y-3 px-4 py-4">
        {jobsError ? (
          <ErrorState onRetry={retryLoadJobs} />
        ) : isLoading ? (
          <SkeletonList />
        ) : feedJobs.length === 0 ? (
          <EmptyState isSearching={Boolean(searchQuery.trim())} onClear={() => setSearchQuery("")} />
        ) : (
          <>
            {visibleJobs.map((job, i) => (
              <div
                key={job.id}
                // Fade-in animation for cards that are newly appended
                className={i >= visibleCount - PAGE_SIZE ? "animate-in fade-in duration-300" : ""}
              >
                <FeedCard
                  job={job}
                  saved={isSaved(job.id)}
                  onOpen={() => openJob(job.id)}
                  onToggleSave={() => toggleSaved(job.id, job)}
                />
              </div>
            ))}

            {/* Sentinel for IntersectionObserver */}
            {hasMore ? (
              <div ref={sentinelRef} className="py-4 text-center">
                <span className="text-xs text-muted-foreground">Loading more…</span>
              </div>
            ) : (
              <div className="py-6 text-center">
                <span className="text-xs text-muted-foreground">
                  You&apos;re all caught up 🎉
                </span>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  )
}

function ErrorState({ onRetry }: { onRetry: () => void }) {
  return (
    <div className="flex flex-col items-center justify-center gap-3 py-20 text-center">
      <AlertCircle className="h-8 w-8 text-destructive" />
      <p className="font-semibold text-foreground">We couldn&apos;t load jobs</p>
      <p className="text-sm text-muted-foreground">
        Please check your connection and try again.
      </p>
      <Button variant="outline" className="mt-2 rounded-xl" onClick={onRetry}>
        Try again
      </Button>
    </div>
  )
}

function EmptyState({ isSearching = false, onClear }: { isSearching?: boolean; onClear?: () => void }) {
  if (isSearching) {
    return (
      <div className="flex flex-col items-center justify-center gap-2 py-16 text-center">
        <p className="font-semibold text-foreground">No matching jobs found</p>
        <p className="text-sm text-muted-foreground">
          Try searching with different keywords or check your spelling.
        </p>
        {onClear && (
          <Button variant="outline" size="sm" className="mt-2 rounded-xl" onClick={onClear}>
            Clear search
          </Button>
        )}
      </div>
    )
  }

  return (
    <div className="flex flex-col items-center justify-center gap-2 py-20 text-center">
      <p className="font-semibold text-foreground">No jobs available right now</p>
      <p className="text-sm text-muted-foreground">Check back soon for new listings.</p>
    </div>
  )
}

function SkeletonList() {
  return (
    <>
      {Array.from({ length: 5 }).map((_, i) => (
        <div key={i} className="rounded-2xl border border-border bg-card p-4 shadow-sm">
          <div className="flex items-start gap-3">
            <div className="h-10 w-10 animate-pulse rounded-full bg-muted" />
            <div className="flex-1 space-y-2">
              <div className="h-3.5 w-3/4 animate-pulse rounded bg-muted" />
              <div className="h-3 w-1/2 animate-pulse rounded bg-muted" />
            </div>
          </div>
          <div className="mt-3 flex gap-2">
            <div className="h-5 w-16 animate-pulse rounded-full bg-muted" />
            <div className="h-5 w-20 animate-pulse rounded-full bg-muted" />
          </div>
        </div>
      ))}
    </>
  )
}
